UPDATE story_character
SET name = #{name}, role_type = #{roleType}, gender = #{gender},
    age_description = #{ageDescription}, appearance = #{appearance}, personality = #{personality},
    background_story = #{backgroundStory}, note = #{note}, current_state_json = #{currentStateJson},
    life_status = #{lifeStatus}, status = #{status}
WHERE project_id = #{projectId} AND character_code = #{characterCode}

